{
  "judgements": [
    {
      "claim_id": "cl-c1693cd980bb",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["period"],
      "reason": "公司说自己在「中南美市场开拓」上「销量同比增长32%」，有对象（中南美市场销量）、有结果（增长32%），但未指明是哪一年/哪一期。"
    },
    {
      "claim_id": "cl-5baf86a08db1",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "公司说2019年「主要产品的毛利率较去年下降」，并给出原因（供给侧改革红利衰减、钢价下行、铁矿石涨价等），对象、期间、指标、结果齐全。"
    },
    {
      "claim_id": "cl-ec2d6f3fd753",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "公司说2020年「持续深耕海外各区域市场」，并给出东南亚、南亚占出口总量46%的具体数据，对象、期间、指标、结果都有。"
    },
    {
      "claim_id": "cl-cc59823d3be0",
      "is_substantive": false,
      "is_template": false,
      "missing_elements": [],
      "reason": "这是表格附注/口径说明（「注：2019年度销售量中包含…不包含…」），属于对数据的注释说明，不是公司经营活动的表述。"
    },
    {
      "claim_id": "cl-9d2ad464d690",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "公司说2019年「出口钢铁产品362.1万吨」，有期间、对象、指标、结果，是实质经营表述；后半句「出口分渠道销售情况如下」为引出表格的过渡语。"
    },
    {
      "claim_id": "cl-6a58d58a539b",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "公司披露截至2015年底持有某公司100%股权、注册资本21.1亿元及经营范围，是对自身持股与子公司情况的实质表述。"
    },
    {
      "claim_id": "cl-d4229bc715c8",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": [],
      "reason": "公司披露截至2015年底持有某公司95.8%股权、注册资本6.2亿元及经营范围，是对自身持股与子公司情况的实质表述。"
    },
    {
      "claim_id": "cl-b9ae44ab9c73",
      "is_substantive": true,
      "is_template": false,
      "missing_elements": ["metric", "result"],
      "reason": "公司说2024年「通过配合政府部门及宝武集团内产量优化调控，实现钢产能的有效发挥」，有对象（钢产能）和期间（2024年），但「有效发挥」没有具体指标和量化结果。"
    }
  ]
}
